// These expected values were read from immutable 4ecab79627d08d1e125391a5831eb995efd3fce4,
// rather than generated by the candidate. per docs/adr/0099-native-factory-orchestration.md:157
const syncCanonicalJSON = `{
  "$schema":"https://opencode.ai/config.json",
  "model":"__DEFAULT_MODEL__","small_model":"__ECONOMY_MODEL__",
  "instructions":["AGENTS.md"],"retained":{"enabled":true,"number":7},
  "permission":{"edit":"deny","bash":{"go *":"allow","rm *":"deny","git status":"allow","*":"ask"}},
  "mcp":{
    "fixture":{"command":["literal tool","two words","$(not-code)"],"env":{"KEY":"literal value"}},
    "disabled":{"command":["never"],"enabled":false},
    "scalar":{"command":"single-tool"}
  },
  "agent":{
    "zeta":{"description":"Future role","model":"old-zeta","permission":{"edit":"ask"}},
    "wiki-maintainer":{"description":"Wiki role","model":"old-wiki","permission":{"edit":"ask"}},
    "spec-writer":{"description":"Spec role","model":"old-spec","permission":{"edit":"ask"}},
    "reviewer":{"description":"Review role","model":"old-review","permission":{"edit":"deny"}},
    "refactorer":{"description":"Refactor role","model":"old-refactor","permission":{"edit":"ask"}},
    "implementer":{"description":"Implement role","model":"old-implement","permission":{"edit":"ask"}}
  }
}`

var syncRoleNames = []string{"implementer", "refactorer", "reviewer", "spec-writer", "wiki-maintainer", "zeta"}

var syncRoleDescriptions = map[string]string{
	"implementer": "Implement role", "refactorer": "Refactor role", "reviewer": "Review role",
	"spec-writer": "Spec role", "wiki-maintainer": "Wiki role", "zeta": "Future role",
}

func syncRoleBody(role string) string {
	return "Instructions for " + role + ".\nmodel: keep this instructional example\nA path C:\\work and a quoted \"word\".\n---\nKeep the body rule and its following paragraph."
}

func syncFixture() (string, string, []string) {
	GinkgoHelper()
	root, cwd, inherited := reportFixture()
	var environment []string
	for _, value := range inherited {
		key, _, _ := strings.Cut(value, "=")
		if !strings.HasPrefix(key, "CLAUDE_") && !strings.HasPrefix(key, "CODEX_") && key != "MODEL_PROVIDER" {
			environment = append(environment, value)
		}
	}
	writeFixture(filepath.Join(root, "opencode.json"), []byte(syncCanonicalJSON), 0600)
	writeFixture(filepath.Join(root, "AGENTS.md"), []byte("Shared instructions.\n"), 0600)
	for _, role := range syncRoleNames {
		writeFixture(filepath.Join(root, ".opencode/agent", role+".md"), []byte("---\ndescription: canonical metadata only\nmode: subagent\nmodel: original-pin\n---\n\n"+syncRoleBody(role)+"\n"), 0600)
	}
	writeFixture(filepath.Join(cwd, "factory.yaml"), []byte("project_name: caller-config\n"), 0600)
	return root, cwd, environment
}

func syncRun(root, cwd string, environment []string, args ...string) cliResult {
	return reportProcess(cwd, environment, filepath.Join(root, "factory"), append([]string{"sync"}, args...))
}

func syncRead(root, path string) string {
	GinkgoHelper()
	data, err := os.ReadFile(filepath.Join(root, path))
	Expect(err).NotTo(HaveOccurred())
	return string(data)
}

func syncJSON(data string) map[string]any {
	GinkgoHelper()
	var value map[string]any
	Expect(json.Unmarshal([]byte(data), &value)).To(Succeed())
	return value
}

func syncWriteJSON(root string, value map[string]any) {
	GinkgoHelper()
	data, err := json.Marshal(value)
	Expect(err).NotTo(HaveOccurred())
	writeFixture(filepath.Join(root, "opencode.json"), data, 0600)
}

func syncClaudeRole(root, role string) (map[string]any, string) {
	GinkgoHelper()
	data := syncRead(root, ".claude/agents/"+role+".md")
	front, found := strings.CutPrefix(data, "---\n")
	Expect(found).To(BeTrue())
	front, body, found := strings.Cut(front, "\n---\n")
	Expect(found).To(BeTrue())
	var metadata map[string]any
	Expect(yaml.Unmarshal([]byte(front), &metadata)).To(Succeed())
	return metadata, strings.Trim(body, "\n")
}

func syncTOMLString(data, key string) (string, bool) {
	GinkgoHelper()
	match := regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(key) + `\s*=\s*("(?:\\.|[^"\\])*")\s*$`).FindStringSubmatch(data)
	if match == nil {
		return "", false
	}
	var value string
	Expect(json.Unmarshal([]byte(match[1]), &value)).To(Succeed())
	return value, true
}

func syncAssertModels(root, harness string, expected map[string]string) {
	GinkgoHelper()
	for _, role := range syncRoleNames {
		switch harness {
		case "opencode":
			config := syncJSON(syncRead(root, "opencode.json"))
			agent := config["agent"].(map[string]any)[role].(map[string]any)
			if expected[role] == "" {
				Expect(agent).NotTo(HaveKey("model"))
			} else {
				Expect(agent["model"]).To(Equal(expected[role]), role)
			}
		case "claude":
			metadata, _ := syncClaudeRole(root, role)
			Expect(metadata["model"]).To(Equal(expected[role]), role)
		case "codex":
			data := syncRead(root, ".codex/agents/"+role+".toml")
			model, exists := syncTOMLString(data, "model")
			Expect(exists).To(Equal(expected[role] != ""), role)
			Expect(model).To(Equal(expected[role]), role)
		}
	}
}

func syncSameModels(value string) map[string]string {
	result := map[string]string{}
	for _, role := range syncRoleNames {
		result[role] = value
	}
	return result
}

func syncConfiguredModels() string {
	return "opencode_default_model: source/default\nopencode_frontier_model: source/frontier\nopencode_economy_model: source/economy\n" +
		"claude_default_model: claude-default\nclaude_frontier_model: claude-frontier\nclaude_economy_model: claude-economy\n" +
		"codex_default_model: codex-default\ncodex_frontier_model: codex-frontier\ncodex_economy_model: codex-economy\n"
}

func syncRefusedWithoutChanges(root, cwd string, environment []string, selector string) {
	GinkgoHelper()
	beforeRoot, beforeCWD := nativeInitArtifacts(root), nativeInitArtifacts(cwd)
	out := syncRun(root, cwd, environment, selector)
	Expect(out.status).To(Equal(1), "%+v", out)
	Expect(out.stderr).NotTo(BeEmpty())
	Expect(nativeInitArtifacts(root)).To(Equal(beforeRoot), "refusal must precede every output publication")
	Expect(nativeInitArtifacts(cwd)).To(Equal(beforeCWD))
}

var _ = Describe("Native orchestration sync generated adapters", func() {
	// per docs/adr/0099-native-factory-orchestration.md:55
	// per docs/adr/0099-native-factory-orchestration.md:58
	// per docs/adr/0099-native-factory-orchestration.md:172
	It("generates Claude permissions, MCP, sorted roles and explicit implementer hooks from the selected assets", func() {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(root, "CLAUDE.md"), []byte("Preserve these private instructions.\n"), 0600)
		out := syncRun(root, cwd, environment, "claude")
		Expect(out.status).To(BeZero(), "%+v", out)
		Expect(out.stderr).To(BeEmpty())
		Expect(syncJSON(syncRead(root, ".claude/settings.json"))).To(Equal(syncJSON(`{
            "$schema":"https://json.schemastore.org/claude-code-settings.json",
            "permissions":{"allow":["Bash(go *)","Bash(git status)"],"deny":["Bash(rm *)","Edit"]},
            "hooks":{"PreToolUse":[{"matcher":"Edit|Write","hooks":[{"type":"command","command":"${CLAUDE_PROJECT_DIR}/scripts/hooks/test-edit-denial.sh","args":[]}]}]}
        }`)))
		Expect(syncJSON(syncRead(root, ".mcp.json"))).To(Equal(syncJSON(`{"mcpServers":{
            "fixture":{"command":"literal tool","args":["two words","$(not-code)"],"env":{"KEY":"literal value"}},
            "scalar":{"command":"single-tool","args":[],"env":{}}
        }}`)))
		last := -1
		for _, role := range syncRoleNames {
			metadata, body := syncClaudeRole(root, role)
			permissionMode := "default"
			if role == "reviewer" {
				permissionMode = "plan"
			}
			expected := map[string]any{"name": role, "description": syncRoleDescriptions[role], "model": "inherit", "permissionMode": permissionMode}
			if role == "implementer" {
				expected["hooks"] = map[string]any{"PreToolUse": []any{map[string]any{"matcher": "Edit|Write", "hooks": []any{map[string]any{"type": "command", "command": "FACTORY_AGENT_ROLE=implementer ${CLAUDE_PROJECT_DIR}/scripts/hooks/test-edit-denial.sh"}}}}}
			}
			Expect(metadata).To(Equal(expected), role)
			Expect(body).To(Equal(syncRoleBody(role)))
			index := strings.Index(out.stdout, ".claude/agents/"+role+".md")
			Expect(index).To(BeNumerically(">", last), "role traversal must be sorted: %s", out.stdout)
			last = index
		}
		Expect(syncRead(root, "CLAUDE.md.replaced-by-symlink")).To(Equal("Preserve these private instructions.\n"))
		link, err := os.Readlink(filepath.Join(root, "CLAUDE.md"))
		Expect(err).NotTo(HaveOccurred())
		Expect(link).To(Equal("AGENTS.md"))
		before, err := os.Lstat(filepath.Join(root, "CLAUDE.md"))
		Expect(err).NotTo(HaveOccurred())
		Expect(syncRun(root, cwd, environment, "claude").status).To(BeZero())
		after, err := os.Lstat(filepath.Join(root, "CLAUDE.md"))
		Expect(err).NotTo(HaveOccurred())
		Expect(os.SameFile(before, after)).To(BeTrue(), "retain the existing compatible link")
		Expect(syncRead(root, "opencode.json")).To(Equal(syncCanonicalJSON))
	})

	// per docs/adr/0099-native-factory-orchestration.md:55
	// per docs/adr/0099-native-factory-orchestration.md:172
	It("generates Codex configuration, readable role bodies, native permissions and only the implementer role hook", func() {
		root, cwd, environment := syncFixture()
		out := syncRun(root, cwd, environment, "codex")
		Expect(out.status).To(BeZero(), "%+v", out)
		config := syncRead(root, ".codex/config.toml")
		Expect(config).To(ContainSubstring("[agents]\nmax_threads = 4\nmax_depth = 1"))
		Expect(config).To(ContainSubstring("[mcp_servers.playwright]\ncommand = \"npx\"\nargs = [\"-y\", \"@playwright/mcp\"]"))
		last := -1
		for _, role := range syncRoleNames {
			data := syncRead(root, ".codex/agents/"+role+".toml")
			name, exists := syncTOMLString(data, "name")
			Expect(exists).To(BeTrue())
			Expect(name).To(Equal(role))
			description, exists := syncTOMLString(data, "description")
			Expect(exists).To(BeTrue())
			Expect(description).To(Equal(syncRoleDescriptions[role]))
			sandbox, exists := syncTOMLString(data, "sandbox_mode")
			Expect(exists).To(BeTrue())
			expectedSandbox := "workspace-write"
			if role == "reviewer" {
				expectedSandbox = "read-only"
			}
			Expect(sandbox).To(Equal(expectedSandbox))
			_, exists = syncTOMLString(data, "model")
			Expect(exists).To(BeFalse(), "unset native tier inherits")
			Expect(data).To(ContainSubstring("developer_instructions = \"\"\"\n"))
			Expect(data).To(ContainSubstring(strings.ReplaceAll(syncRoleBody(role), `\`, `\\`)))
			if role == "implementer" {
				Expect(data).To(ContainSubstring("[[hooks.PreToolUse]]\nmatcher = \"^(apply_patch|Edit|Write)$\""))
				Expect(data).To(ContainSubstring("command = 'FACTORY_AGENT_ROLE=implementer \"$(git rev-parse --show-toplevel)/scripts/hooks/test-edit-denial.sh\"'"))
				Expect(data).To(ContainSubstring("timeout = 30\nstatusMessage = \"Enforcing implementer test-file boundary\""))
			} else {
				Expect(data).NotTo(ContainSubstring("[[hooks."))
			}
			index := strings.Index(out.stdout, ".codex/agents/"+role+".toml")
			Expect(index).To(BeNumerically(">", last), "role traversal must be sorted")
			last = index
		}
		Expect(syncRead(root, "opencode.json")).To(Equal(syncCanonicalJSON))
	})

	// per docs/adr/0099-native-factory-orchestration.md:240
	It("escapes DEL in Codex descriptions without changing the decoded canonical value", func() {
		root, cwd, environment := syncFixture()
		description := "Canonical \x7f description"
		canonical := syncJSON(syncCanonicalJSON)
		canonical["agent"].(map[string]any)["implementer"].(map[string]any)["description"] = description
		syncWriteJSON(root, canonical)
		result := syncRun(root, cwd, environment, "codex")
		Expect(result.status).To(BeZero(), "%+v", result)
		for _, path := range []string{".codex/config.toml", ".codex/agents/implementer.toml"} {
			data := syncRead(root, path)
			Expect(data).NotTo(ContainSubstring("\x7f"), "TOML forbids literal DEL: %s", path)
		}
		role := syncRead(root, ".codex/agents/implementer.toml")
		Expect(role).To(ContainSubstring(`\u007f`))
		decoded, exists := syncTOMLString(role, "description")
		Expect(exists).To(BeTrue())
		Expect(decoded).To(Equal(description))
	})

	// per docs/adr/0099-native-factory-orchestration.md:57
	It("leaves OpenCode byte-for-byte intact when no harness setting activates synchronization", func() {
		root, cwd, environment := syncFixture()
		before := nativeInitArtifacts(root)
		out := syncRun(root, cwd, environment, "opencode")
		Expect(out.status).To(BeZero(), "%+v", out)
		Expect(out.stdout).To(ContainSubstring("no harness settings configured"))
		Expect(nativeInitArtifacts(root)).To(Equal(before))
	})

	// per docs/adr/0099-native-factory-orchestration.md:57
	// per docs/adr/0099-native-factory-orchestration.md:68
	It("removes activated blank OpenCode pins only from metadata while retaining all body bytes", func() {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte("opencode_default_model:\n"), 0600)
		out := syncRun(root, cwd, environment, "opencode")
		Expect(out.status).To(BeZero(), "%+v", out)
		expected := syncJSON(syncCanonicalJSON)
		delete(expected, "model")
		delete(expected, "small_model")
		for _, agent := range expected["agent"].(map[string]any) {
			delete(agent.(map[string]any), "model")
		}
		Expect(syncJSON(syncRead(root, "opencode.json"))).To(Equal(expected))
		for _, role := range syncRoleNames {
			Expect(syncRead(root, ".opencode/agent/"+role+".md")).To(Equal("---\ndescription: canonical metadata only\nmode: subagent\n---\n\n" + syncRoleBody(role) + "\n"))
		}
	})

	// per docs/adr/0099-native-factory-orchestration.md:55
	DescribeTable("routes each harness by role tier and collapses economy only for the standard profile", func(harness, profile, prefix string) {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte(syncConfiguredModels()+"cost_profile: "+profile+"\n"), 0600)
		out := syncRun(root, cwd, environment, harness)
		Expect(out.status).To(BeZero(), "%+v", out)
		expected := map[string]string{"implementer": prefix + "default", "refactorer": prefix + "default", "reviewer": prefix + "frontier", "spec-writer": prefix + "frontier", "wiki-maintainer": prefix + "default", "zeta": prefix + "default"}
		if profile == "economy" {
			expected["refactorer"], expected["wiki-maintainer"] = prefix+"economy", prefix+"economy"
		}
		syncAssertModels(root, harness, expected)
		if harness == "opencode" {
			config := syncJSON(syncRead(root, "opencode.json"))
			Expect(config["model"]).To(Equal("source/default"))
			small := "source/default"
			if profile == "economy" {
				small = "source/economy"
			}
			Expect(config["small_model"]).To(Equal(small))
			for _, role := range syncRoleNames {
				Expect(syncRead(root, ".opencode/agent/"+role+".md")).To(Equal("---\ndescription: canonical metadata only\nmode: subagent\nmodel: " + expected[role] + "\n---\n\n" + syncRoleBody(role) + "\n"))
			}
		}
	},
		Entry("OpenCode standard", "opencode", "standard", "source/"), Entry("OpenCode economy", "opencode", "economy", "source/"),
		Entry("Claude standard", "claude", "standard", "claude-"), Entry("Claude economy", "claude", "economy", "claude-"),
		Entry("Codex standard", "codex", "standard", "codex-"), Entry("Codex economy", "codex", "economy", "codex-"))

	// per docs/adr/0099-native-factory-orchestration.md:55
	DescribeTable("uses native harness inheritance for blank, cross-provider or unresolved model tiers", func(model string) {
		root, cwd, environment := syncFixture()
		for _, harness := range []string{"claude", "codex"} {
			upper := strings.ToUpper(harness)
			selected := append(append([]string{}, environment...), upper+"_DEFAULT_MODEL="+model, upper+"_FRONTIER_MODEL="+model, upper+"_ECONOMY_MODEL="+model)
			out := syncRun(root, cwd, selected, harness)
			Expect(out.status).To(BeZero(), "%+v", out)
			expected := ""
			if harness == "claude" {
				expected = "inherit"
			}
			syncAssertModels(root, harness, syncSameModels(expected))
		}
	}, Entry("blank", ""), Entry("cross provider", "provider/model"), Entry("unresolved placeholder", "__DEFAULT_MODEL__"))

	// per docs/adr/0099-native-factory-orchestration.md:67
	It("treats model punctuation and shell syntax as literal data and changes no instructional model example", func() {
		root, cwd, environment := syncFixture()
		literal := `native&|\replacement "quoted" $(touch SYNC_INJECTION)`
		environment = append(environment, "OPENCODE_DEFAULT_MODEL="+literal, "CLAUDE_DEFAULT_MODEL="+literal, "CODEX_DEFAULT_MODEL="+literal)
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte("cost_profile: standard\n"), 0600)
		out := syncRun(root, cwd, environment, "all")
		Expect(out.status).To(BeZero(), "%+v", out)
		syncAssertModels(root, "opencode", syncSameModels(literal))
		for _, harness := range []string{"claude", "codex"} {
			// Frontier has no setting, so its native parent model remains inherited.
			expected := syncSameModels(literal)
			inherited := ""
			if harness == "claude" {
				inherited = "inherit"
			}
			expected["reviewer"], expected["spec-writer"] = inherited, inherited
			syncAssertModels(root, harness, expected)
		}
		for _, role := range syncRoleNames {
			Expect(syncRead(root, ".opencode/agent/"+role+".md")).To(HaveSuffix("---\n\n" + syncRoleBody(role) + "\n"))
		}
		for _, path := range []string{root, cwd} {
			_, err := os.Stat(filepath.Join(path, "SYNC_INJECTION"))
			Expect(os.IsNotExist(err)).To(BeTrue())
		}
	})
})

var _ = Describe("Native orchestration sync configuration and command selection", func() {
	// per docs/adr/0099-native-factory-orchestration.md:49
	DescribeTable("keeps caller configuration precedence separate from the output asset root", func(kind, expected string) {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(root, "factory.yaml"), []byte("opencode_default_model: wrong/asset-root\n"), 0600)
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte("opencode_default_model: yaml/model\n"), 0600)
		writeFixture(filepath.Join(cwd, "factory.config"), []byte("OPENCODE_DEFAULT_MODEL=legacy/model\n"), 0600)
		switch kind {
		case "legacy":
			writeFixture(filepath.Join(cwd, "factory.yaml"), []byte("opencode_default_model:\n"), 0600)
		case "caller":
			environment = append(environment, "OPENCODE_DEFAULT_MODEL=caller/model")
		case "empty caller":
			environment = append(environment, "OPENCODE_DEFAULT_MODEL=")
		case "override":
			writeFixture(filepath.Join(cwd, "chosen.yaml"), []byte("opencode_default_model: chosen/model\n"), 0600)
			environment = append(environment, "FACTORY_CONFIG=chosen.yaml")
		}
		beforeCWD := nativeInitArtifacts(cwd)
		out := syncRun(root, cwd, environment, "opencode")
		Expect(out.status).To(BeZero(), "%+v", out)
		syncAssertModels(root, "opencode", syncSameModels(expected))
		Expect(nativeInitArtifacts(cwd)).To(Equal(beforeCWD), "read caller settings, publish only below selected assets")
		Expect(syncRead(root, "factory.yaml")).To(Equal("opencode_default_model: wrong/asset-root\n"))
	}, Entry("parsed legacy fallback", "legacy", "legacy/model"), Entry("nonempty YAML", "yaml", "yaml/model"), Entry("caller value", "caller", "caller/model"), Entry("explicit empty caller", "empty caller", ""), Entry("explicit relative configuration", "override", "chosen/model"))

	// per docs/adr/0099-native-factory-orchestration.md:49
	It("selects a caller Git-root configuration from a nested cwd while writing the independent assets", func() {
		root, cwd, environment := syncFixture()
		doctorGit(cwd, environment, "init", "-q")
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte("opencode_default_model: git/root-model\n"), 0600)
		nested := filepath.Join(cwd, "nested/deeper")
		Expect(os.MkdirAll(nested, 0700)).To(Succeed())
		out := syncRun(root, nested, environment, "opencode")
		Expect(out.status).To(BeZero(), "%+v", out)
		syncAssertModels(root, "opencode", syncSameModels("git/root-model"))
		entries, err := os.ReadDir(nested)
		Expect(err).NotTo(HaveOccurred())
		Expect(entries).To(BeEmpty())
	})

	// per docs/adr/0099-native-factory-orchestration.md:26
	// per docs/adr/0099-native-factory-orchestration.md:69
	DescribeTable("runs every harness sequentially in OpenCode, Claude, Codex order", func(args []string) {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte(syncConfiguredModels()), 0600)
		out := syncRun(root, cwd, environment, args...)
		Expect(out.status).To(BeZero(), "%+v", out)
		opencode, claude, codex := strings.Index(out.stdout, "sync-opencode:"), strings.Index(out.stdout, "sync-claude:"), strings.Index(out.stdout, "sync-codex:")
		Expect(opencode).To(BeNumerically(">=", 0))
		Expect(claude).To(BeNumerically(">", opencode))
		Expect(codex).To(BeNumerically(">", claude))
		Expect(strings.LastIndex(out.stdout, "sync-opencode:")).To(BeNumerically("<", claude))
		Expect(strings.LastIndex(out.stdout, "sync-claude:")).To(BeNumerically("<", codex))
		Expect(syncRead(root, ".claude/agents/implementer.md")).To(ContainSubstring(syncRoleBody("implementer")))
		Expect(syncRead(root, ".codex/agents/implementer.toml")).To(ContainSubstring("sandbox_mode"))
		Expect(syncJSON(syncRead(root, "opencode.json"))["model"]).To(Equal("source/default"))
	}, Entry("implicit all", []string{}), Entry("explicit all", []string{"all"}))

	// per docs/adr/0099-native-factory-orchestration.md:26
	It("shows inert sync help without parsing or touching broken inputs", func() {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(root, "opencode.json"), []byte("{broken"), 0600)
		before := nativeInitArtifacts(root)
		out := syncRun(root, cwd, environment, "--help")
		Expect(out.status).To(BeZero(), "%+v", out)
		Expect(out.stdout).To(ContainSubstring("sync"))
		for _, selector := range []string{"all", "opencode", "claude", "codex"} {
			Expect(out.stdout).To(ContainSubstring(selector))
		}
		Expect(out.stderr).To(BeEmpty())
		Expect(nativeInitArtifacts(root)).To(Equal(before))
	})

	// per docs/adr/0099-native-factory-orchestration.md:27
	DescribeTable("rejects invalid selectors and extra public operands before writes", func(args []string) {
		root, cwd, environment := syncFixture()
		before := nativeInitArtifacts(root)
		out := syncRun(root, cwd, environment, args...)
		Expect(out.status).To(Equal(2), "%+v", out)
		Expect(out.stderr).To(ContainSubstring("sync"))
		Expect(out.stderr).NotTo(ContainSubstring("unknown command 'sync'"))
		Expect(nativeInitArtifacts(root)).To(Equal(before))
	}, Entry("unknown harness", []string{"unrecognized"}), Entry("extra operand", []string{"claude", "ignored"}))
})

var _ = Describe("Native orchestration sync publication safety", func() {
	// per docs/adr/0099-native-factory-orchestration.md:63
	It("validates a later missing role before changing any all-harness output", func() {
		root, cwd, environment := syncFixture()
		writeFixture(filepath.Join(cwd, "factory.yaml"), []byte(syncConfiguredModels()), 0600)
		Expect(os.Remove(filepath.Join(root, ".opencode/agent/zeta.md"))).To(Succeed())
		writeFixture(filepath.Join(root, ".claude/settings.json"), []byte("private settings"), 0600)
		writeFixture(filepath.Join(root, ".codex/config.toml"), []byte("private config"), 0600)
		syncRefusedWithoutChanges(root, cwd, environment, "all")
	})

	// per docs/adr/0099-native-factory-orchestration.md:63
	It("rejects traversal agent identifiers even when their escaped canonical role exists", func() {
		root, cwd, environment := syncFixture()
		config := syncJSON(syncCanonicalJSON)
		config["agent"].(map[string]any)["../escaped"] = map[string]any{"description": "Escaped role", "permission": map[string]any{"edit": "ask"}}
		syncWriteJSON(root, config)
		writeFixture(filepath.Join(root, ".opencode/escaped.md"), []byte("---\nmodel: original\n---\nEscaped instructions.\n"), 0600)
		syncRefusedWithoutChanges(root, cwd, environment, "all")
	})

	// per docs/adr/0099-native-factory-orchestration.md:63
	DescribeTable("preserves foreign data when an output or parent is a symbolic link", func(kind string) {
		root, cwd, environment := syncFixture()
		foreign := filepath.Join(filepath.Dir(root), "foreign outputs")
		writeFixture(filepath.Join(foreign, "keep"), []byte("private foreign bytes"), 0600)
		selector := "claude"
		switch kind {
		case "parent":
			Expect(os.Symlink(foreign, filepath.Join(root, ".claude"))).To(Succeed())
		case "settings":
			Expect(os.MkdirAll(filepath.Join(root, ".claude"), 0700)).To(Succeed())
			Expect(os.Symlink(filepath.Join(foreign, "keep"), filepath.Join(root, ".claude/settings.json"))).To(Succeed())
		case "role":
			selector = "codex"
			Expect(os.MkdirAll(filepath.Join(root, ".codex/agents"), 0700)).To(Succeed())
			Expect(os.Symlink(filepath.Join(foreign, "keep"), filepath.Join(root, ".codex/agents/implementer.toml"))).To(Succeed())
		case "unrelated CLAUDE link":
			Expect(os.Symlink(filepath.Join(foreign, "keep"), filepath.Join(root, "CLAUDE.md"))).To(Succeed())
		}
		before := nativeInitArtifacts(foreign)
		syncRefusedWithoutChanges(root, cwd, environment, selector)
		Expect(nativeInitArtifacts(foreign)).To(Equal(before))
	}, Entry("unsafe Claude parent", "parent"), Entry("linked Claude settings", "settings"), Entry("linked Codex role", "role"), Entry("unrelated instruction link", "unrelated CLAUDE link"))

	// per docs/adr/0099-native-factory-orchestration.md:63
	// per docs/adr/0099-native-factory-orchestration.md:174
	DescribeTable("refuses invalid source formats before any generated output is published", func(kind string) {
		root, cwd, environment := syncFixture()
		switch kind {
		case "json":
			writeFixture(filepath.Join(root, "opencode.json"), []byte("{ invalid JSON"), 0600)
		case "agent type":
			config := syncJSON(syncCanonicalJSON)
			config["agent"].(map[string]any)["zeta"] = []any{"unsupported"}
			syncWriteJSON(root, config)
		case "frontmatter":
			writeFixture(filepath.Join(root, ".opencode/agent/zeta.md"), []byte("No frontmatter.\nmodel: body example\n"), 0600)
		}
		syncRefusedWithoutChanges(root, cwd, environment, "all")
	}, Entry("malformed JSON", "json"), Entry("unsupported agent data", "agent type"), Entry("missing role frontmatter", "frontmatter"))

	// per docs/adr/0099-native-factory-orchestration.md:69
	It("never overwrites occupied CLAUDE backup names when timestamps collide", func() {
		root, cwd, environment := syncFixture()
		original := "Private instructions needing a new backup.\n"
		writeFixture(filepath.Join(root, "CLAUDE.md"), []byte(original), 0600)
		base := "CLAUDE.md.replaced-by-symlink"
		occupied := map[string]string{base: "preexisting unsuffixed backup"}
		// Cover the bounded child lifetime in the old timestamp namespace without
		// making the candidate's clock or backup-name algorithm an oracle.
		for offset := -60; offset <= 60; offset++ {
			path := base + "." + time.Now().Add(time.Duration(offset)*time.Second).Format("20060102150405")
			occupied[path] = fmt.Sprintf("private old backup %d", offset)
		}
		for path, data := range occupied {
			writeFixture(filepath.Join(root, path), []byte(data), 0600)
		}
		before := nativeInitArtifacts(root)
		out := syncRun(root, cwd, environment, "claude")
		Expect(out.status).To(BeElementOf(0, 1), "%+v", out)
		for path, data := range occupied {
			Expect(syncRead(root, path)).To(Equal(data), "occupied backup %s", path)
		}
		if out.status == 1 {
			Expect(nativeInitArtifacts(root)).To(Equal(before), "a refused backup must precede publication")
			return
		}
		link, err := os.Readlink(filepath.Join(root, "CLAUDE.md"))
		Expect(err).NotTo(HaveOccurred())
		Expect(link).To(Equal("AGENTS.md"))
		backups, err := filepath.Glob(filepath.Join(root, base+"*"))
		Expect(err).NotTo(HaveOccurred())
		found := false
		for _, path := range backups {
			if syncRead(root, filepath.Base(path)) == original {
				found = true
			}
		}
		Expect(found).To(BeTrue(), "successful displacement must leave a distinct, complete local backup")
	})
})
